<script setup>import{onMounted}from'vue';import PageShell from'../components/PageShell.vue';import MovieCard from'../components/MovieCard.vue';import StatusPanel from'../components/StatusPanel.vue';import{useMovieStore}from'../stores/movie';const store=useMovieStore();onMounted(()=>store.loadMovies(true).catch(()=>{}))</script>
<template><PageShell><section class="page-banner"><span class="eyebrow">MY COLLECTION</span><h1>我的收藏</h1><p>把喜欢的电影留在这里，随时开启下一段光影旅程。</p></section><section class="content-section"><div v-if="store.favorites.length" class="section-heading"><div><h2>{{store.favorites.length}} 部收藏电影</h2><p>收藏数据保存在当前浏览器</p></div><button class="danger-button" @click="store.clearFavorites">清空收藏</button></div><StatusPanel v-if="!store.favorites.length" icon="♡" title="收藏夹还是空的" text="遇到喜欢的电影，点击心形按钮收藏吧"/><div v-else class="movie-grid"><MovieCard v-for="(movie,i) in store.favorites" :key="movie.movieid" :movie="movie" :index="i"/></div></section></PageShell></template>
